  // C5a: field-sensitive function-pointer target facts.  These records reuse
  // the existing function-pointer target representation (FunctionDecl target
  // identities plus target-set semantics), but keep field facts separate from
  // ordinary function-pointer variables.  C5a is discovery/reporting only; C5b
  // will consume the field target sets to resolve ops->fn(...) calls.
  struct FieldFunctionPointerTargetRecord {
    std::string fieldEntity;
    std::string baseEntity;
    std::string fieldPath;
    std::string fieldType;
    std::string bindingKind;
    std::string sourceExpr;
    std::string sourceKind;
    std::vector<std::string> targets;
    std::vector<std::string> qualifiedTargets;
    std::vector<std::string> signatureKeys;
    std::optional<Guard> guard;
    SourceSpan span;
  };

  // C5d: readable, structured resolution records for calls through
  // function-pointer fields.  C5a records the field target facts; C5b/C5c
  // consume them.  These records explain which guarded target alternatives were
  // consumed at each ops.fn(...) / ops->fn(...) call site, without changing the
  // propagation semantics.
  struct FieldFunctionPointerCallResolutionRecord {
    std::string caller;
    std::string calleeExpr;
    std::string fieldEntity;
    std::string resolutionKind;
    std::string status;
    std::string target;
    std::string qualifiedName;
    std::string signatureKey;
    bool composed = false;
    std::optional<Guard> guard;
    SourceSpan span;
  };

  // C6g5f4: report-only fact for any invocation through a function-pointer
  // field.  A target may be unresolved at the invocation site (for example,
  // invoke(dispatch, value)); that still distinguishes a field callback carrier
  // from an ordinary function-pointer formal parameter.  This record is never
  // used by solving or propagation.
  struct FieldCallbackInvocationRecord {
    std::string caller;
    std::string calleeExpr;
    std::string fieldEntity;
    std::string fieldPath;
    bool hasResolvedTarget = false;
    std::optional<Guard> guard;
    SourceSpan span;
  };

