  std::vector<const EntityKey *> sortedObservationEntities() const {
    std::vector<const EntityKey *> keys;
    keys.reserve(entityObservations.size());
    for (const auto &entry : entityObservations)
      keys.push_back(&entry.first);

    std::sort(keys.begin(), keys.end(),
              [this](const EntityKey *a, const EntityKey *b) {
                return renderEntity(*a) < renderEntity(*b);
              });
    return keys;
  }

  std::vector<const EntityKey *> sortedPointerUseEntities() const {
    std::vector<const EntityKey *> keys;
    keys.reserve(pointerUses.size());
    for (const auto &entry : pointerUses)
      keys.push_back(&entry.first);

    std::sort(keys.begin(), keys.end(),
              [this](const EntityKey *a, const EntityKey *b) {
                return renderEntity(*a) < renderEntity(*b);
              });
    return keys;
  }

  json::Object castHistoryComponentsJson(
      const std::optional<std::string> &baseText,
      const std::optional<TypeAtom> &baseAtom,
      const ObsHistPtr &tail) const {
    json::Object obj{{"baseText", baseText ? *baseText : std::string()},
                     {"tail", historySummaryJson(tail)}};

    if (baseAtom)
      obj["baseAtom"] = typeAtomJson(*baseAtom);
    else
      obj["baseAtom"] = json::Value(nullptr);

    return obj;
  }

  json::Array emitDirectCastHistoriesJson() const {
    json::Array arr;
    for (const EntityKey *entity : sortedObservationEntities()) {
      DirectHistoryComponents c = directCastHistoryComponentsForEntity(*entity);
      if (isPureFunctionDesignatorDecay(*entity, c))
        continue;

      auto rendered = directCastHistoryForEntity(*entity);

      arr.push_back(json::Object{
          {"entity", renderEntity(*entity)},
          {"history", rendered ? *rendered : std::string("<none>")},
          {"components", castHistoryComponentsJson(c.baseText, c.baseAtom, c.tail)}});
    }
    return arr;
  }

  json::Array emitStorageCastHistoriesJson() const {
    json::Array arr;
    for (const EntityKey *entity : sortedObservationEntities()) {
      if (!isStorageLocationEntity(*entity))
        continue;

      StorageHistoryComponents c = storageCastHistoryComponentsForEntity(*entity);
      auto rendered = storageCastHistoryForEntity(*entity);
      if (!rendered)
        continue;

      arr.push_back(json::Object{
          {"entity", renderEntity(*entity)},
          {"history", *rendered},
          {"components", castHistoryComponentsJson(c.baseText, c.baseAtom, c.tail)}});
    }
    return arr;
  }

  json::Array emitRawObservationsJson() const {
    json::Array arr;
    for (const EntityKey *entity : sortedObservationEntities()) {
      auto it = entityObservations.find(*entity);
      if (it == entityObservations.end())
        continue;

      json::Array obsArray;
      for (const auto &obs : it->second) {
        json::Object obj{
            {"observation", historySummaryJson(obs.obs)},
            {"attachPath", historySummaryJson(obs.attachPath)},
            {"provenance", obs.provenance},
            {"role", obs.provenance.empty()
                         ? std::string()
                         : std::string(observationRoleName(obs.provenance))},
            {"location", sourceSpanJson(obs.span)}};

        if (obs.guard)
          obj["guard"] = guardJson(*obs.guard);
        else
          obj["guard"] = json::Value(nullptr);

        obsArray.push_back(std::move(obj));
      }

      arr.push_back(json::Object{{"entity", renderEntity(*entity)},
                                 {"observations", std::move(obsArray)}});
    }
    return arr;
  }

  json::Array emitDerivedObservationSummariesJson() const {
    json::Array arr;
    for (const EntityKey *entity : sortedObservationEntities()) {
      json::Object obj{{"entity", renderEntity(*entity)},
                       {"grouped", groupedSummaryForEntity(*entity)}};

      if (auto branch = branchCastSummaryForEntity(*entity))
        obj["branchCast"] = *branch;
      else
        obj["branchCast"] = json::Value(nullptr);

      arr.push_back(std::move(obj));
    }
    return arr;
  }

  json::Object pointerUseSummaryJson(
      const EntityKey &entity,
      const std::vector<PointerUseRecord> &entityUses) const {
    json::Array uses;
    for (const auto &use : entityUses)
      uses.push_back(pointerUseJson(use));

    return json::Object{{"entity", renderEntity(entity)},
                        {"uses", std::move(uses)},
                        {"operationGroups",
                         pointerUseOperationGroupsJson(&entityUses)},
                        {"semanticOperationGroups",
                         semanticPointerOperationGroupsJson(&entityUses)}};
  }

  json::Array emitPointerUseSummariesJson() const {
    json::Array arr;
    for (const EntityKey *entity : sortedPointerUseEntities()) {
      auto it = pointerUses.find(*entity);
      if (it == pointerUses.end())
        continue;
      arr.push_back(pointerUseSummaryJson(*entity, it->second));
    }
    return arr;
  }

  json::Array emitReturnAliasPointerUseContinuationsJson() const {
    json::Array arr;
    for (const auto &rec : collectReturnAliasPointerUseContinuations()) {
      const PointerUseRecord &use = rec.use;
      json::Object operation{
          {"kind", pointerUseKindName(use.kind)},
          {"pointerType", use.pointerType},
          {"detail", use.detail},
          {"location", sourceSpanJson(use.span)}};
      if (use.accessType)
        operation["accessType"] = *use.accessType;
      else
        operation["accessType"] = json::Value(nullptr);
      if (use.guard)
        operation["guard"] = guardJson(*use.guard);
      else
        operation["guard"] = json::Value(nullptr);
      operation["provenance"] = pointerUseProvenanceJson(use.provenance);

      arr.push_back(json::Object{
          {"sourceEntity", renderEntity(rec.sourceEntity)},
          {"reason", rec.reason},
          {"provenanceAttachPath", historySummaryJson(use.attachPath)},
          {"semanticAttachPath", historySummaryJson(rec.semanticAttachPath)},
          {"operation", std::move(operation)},
          {"pointerUse", pointerUseJson(use)},
          {"note", "C4Q1 reporting-only fact: the actual propagated pointer-use payload remains in pointerUseSummaries; this record explains that the payload reached the source entity through a returned alias."}});
    }
    return arr;
  }

  json::Array emitReturnAliasPointerUseContinuationsLinkJson() const {
    // The project builder only requires the structured attachment IR and the
    // operation payload.  Deliberately omit report-only prose and rendered
    // histories from the C2 interchange representation.
    json::Array arr;
    for (const auto &rec : collectReturnAliasPointerUseContinuations()) {
      const PointerUseRecord &use = rec.use;
      json::Object operation{
          {"kind", pointerUseKindName(use.kind)},
          {"pointerType", use.pointerType},
          {"detail", use.detail},
          {"location", sourceSpanJson(use.span)}};
      if (use.accessType)
        operation["accessType"] = *use.accessType;
      else
        operation["accessType"] = json::Value(nullptr);
      if (use.guard)
        operation["guard"] = guardJson(*use.guard);
      else
        operation["guard"] = json::Value(nullptr);
      operation["provenance"] = pointerUseProvenanceJson(use.provenance);

      arr.push_back(json::Object{
          {"sourceEntity", renderEntity(rec.sourceEntity)},
          {"reason", rec.reason},
          {"provenanceAttachPath", historyLinkSummaryJson(use.attachPath)},
          {"semanticAttachPath", historyLinkSummaryJson(rec.semanticAttachPath)},
          {"operation", std::move(operation)},
          {"pointerUse", pointerUseLinkJson(use)}});
    }
    return arr;
  }

  json::Object entityPointerBehaviorJson(
      const EntityKey &entity,
      const DirectHistoryComponents &components,
      const std::vector<PointerUseRecord> *uses) const {
    HistoryMetrics m =
        computeHistoryMetrics(components.tail, components.baseText, uses,
                              components.baseAtom);
    HistoryShapeClass shape = classifyHistoryShape(m);
    HistoryRiskClass historyRisk = classifyHistoryRisk(m, components.baseText);
    WildPointerBehaviorMetrics wm =
        computeWildPointerBehaviorMetrics(m, uses);
    const FunctionDecl *entityFunction = paperEnclosingFunction(entity);
    CallbackMediationState callbackState =
        callbackMediationStateForFunction(entityFunction, m, uses);
    WildPointerBehaviorClass behavior =
        classifyWildPointerBehavior(m, uses, callbackState);
    PointerUseEvidenceMetrics evidence = behaviorEvidenceForEntity(entity, uses);
    PaperWildnessSummary paper =
        computePaperWildnessSummary(m, wm, historyRisk, behavior);
    SemanticMediationSummary mediation =
        computeSemanticMediationSummary(uses, paper, behavior, callbackState);

    bool isParamEntity =
        entity.kind == EntityKey::Kind::ValueDeclEntity &&
        entity.decl && isa<ParmVarDecl>(entity.decl);
    ViewCompletenessClass view =
        classifyViewCompleteness(m, wm, isParamEntity,
                                 isStorageLocationEntity(entity));

    json::Object obj{
        {"entity", renderEntity(entity)},
        {"view", viewCompletenessClassName(view)},
        {"historyShape", historyShapeClassName(shape)},
        {"historyRisk", historyRiskClassName(historyRisk)},
        {"behavior", wildPointerBehaviorClassName(behavior)},
        {"callbackMediationState", callbackMediationStateName(callbackState)},
        {"wildLike", wm.wildLike},
        {"history", directCastHistoryForEntity(entity).value_or("<none>")},
        {"metrics", historyMetricsJson(m, shape, historyRisk, behavior)},
        {"wildPointerMetrics", wildPointerMetricsJson(wm)},
        {"paperWildness", paperWildnessJson(paper)},
        {"semanticMediation", semanticMediationJson(mediation)},
        {"stableClassification",
         stableClassificationJson(
             "entity", renderEntity(entity),
             wildPointerBehaviorClassName(behavior), mediation,
             historyRiskClassName(historyRisk),
             pointerUseEvidenceSourceKind(evidence),
             entity.decl ? static_cast<const Decl *>(entity.decl)
                         : static_cast<const Decl *>(entity.function))},
        {"behaviorEvidence", behaviorEvidenceJson(evidence, uses)},
        {"components",
         castHistoryComponentsJson(components.baseText, components.baseAtom,
                                   components.tail)}};

    if (view == ViewCompletenessClass::PartialView ||
        view == ViewCompletenessClass::LocalView ||
        view == ViewCompletenessClass::DebugOnlyView) {
      obj["viewNote"] =
          "intermediate/local view; downstream operation evidence may be projected to an earlier root or function parameter";
    }

    return obj;
  }

  json::Array emitPointerBehaviorMetricsJson() const {
    json::Array arr;
    for (const EntityKey *entity : sortedObservationEntities()) {
      DirectHistoryComponents components =
          directCastHistoryComponentsForEntity(*entity);
      if (isPureFunctionDesignatorDecay(*entity, components))
        continue;

      const auto *uses = pointerUsesForEntity(*entity);
      arr.push_back(entityPointerBehaviorJson(*entity, components, uses));
    }
    return arr;
  }

  json::Array emitStorageHistoryMetricsJson() const {
    json::Array arr;
    for (const EntityKey *entity : sortedObservationEntities()) {
      if (!isStorageLocationEntity(*entity))
        continue;

      StorageHistoryComponents components =
          storageCastHistoryComponentsForEntity(*entity);
      if (!components.baseText && !components.tail)
        continue;

      const auto *uses = pointerUsesForEntity(*entity);
      HistoryMetrics m =
          computeHistoryMetrics(components.tail, components.baseText, uses,
                                components.baseAtom);
      HistoryShapeClass shape = classifyHistoryShape(m);
      HistoryRiskClass risk = classifyHistoryRisk(m, components.baseText);
      WildPointerBehaviorClass behavior =
          classifyWildPointerBehavior(m, uses);
      BranchCastMetrics bm =
          computeBranchCastMetrics(components.tail, components.baseText, uses);

      json::Object obj{
          {"entity", renderEntity(*entity)},
          {"history", storageCastHistoryForEntity(*entity).value_or("<none>")},
          {"historyShape", historyShapeClassName(shape)},
          {"historyRisk", historyRiskClassName(risk)},
          {"metrics", historyMetricsJson(m, shape, risk, behavior)},
          {"branchMetrics", branchCastMetricsJson(bm)},
          {"components",
           castHistoryComponentsJson(components.baseText, components.baseAtom,
                                     components.tail)}};

      arr.push_back(std::move(obj));
    }
    return arr;
  }

  json::Array emitFunctionParameterBehaviorMetricsJson() const {
    json::Array arr;

    for (const auto &entry : functionSummaries) {
      const FunctionDecl *fd = entry.first;
      const FunctionSummary &fs = entry.second;
      auto useIt = findByFunctionIdentity(functionParamUseSummaries, fd);

      for (size_t i = 0; i < fs.params.size(); ++i) {
        std::optional<std::string> base = fs.params[i].declaredType.text;
        const std::vector<PointerUseRecord> *uses = nullptr;
        if (useIt != functionParamUseSummaries.end() &&
            i < useIt->second.size())
          uses = &useIt->second[i];

        std::optional<TypeAtom> baseAtom = std::nullopt;
        std::string paramName;
        const ParmVarDecl *pd = nullptr;
        if (fd && i < fd->getNumParams()) {
          pd = fd->getParamDecl(static_cast<unsigned>(i));
          baseAtom = typeAtomFromQualType(pd->getType());
          paramName = pd->getNameAsString();
        }

        HistoryMetrics m =
            computeHistoryMetrics(fs.params[i].obsSummary, base, uses, baseAtom);
        HistoryShapeClass shape = classifyHistoryShape(m);
        HistoryRiskClass risk = classifyHistoryRisk(m, base);
        WildPointerBehaviorMetrics wm =
            computeWildPointerBehaviorMetrics(m, uses);
        CallbackMediationState callbackState =
            callbackMediationStateForFunction(fd, m, uses);
        WildPointerBehaviorClass behavior =
            classifyWildPointerBehavior(m, uses, callbackState);
        PointerUseEvidenceMetrics evidence = computePointerUseEvidenceMetrics(uses);
        PaperWildnessSummary paper =
            computePaperWildnessSummary(m, wm, risk, behavior);
        SemanticMediationSummary mediation =
            computeSemanticMediationSummary(uses, paper, behavior, callbackState);
        ViewCompletenessClass view =
            classifyViewCompleteness(m, wm, true, false);
        FunctionParameterRoleClass role =
            classifyFunctionParameterRole(fs.params[i].declaredType, m,
                                          callbackState);

        if (!wm.wildLike && !fs.params[i].obsSummary &&
            role == FunctionParameterRoleClass::OrdinaryParameter)
          continue;

        arr.push_back(json::Object{
            {"function", fs.name},
            {"paramIndex", static_cast<int64_t>(i)},
            {"paramName", paramName},
            {"declaredType", fs.params[i].declaredType.text},
            {"declaredTypeAtom", typeAtomJson(fs.params[i].declaredType)},
            {"summary", historySummaryJson(fs.params[i].obsSummary)},
            {"paramRole", functionParameterRoleClassName(role)},
            {"callbackMediationState", callbackMediationStateName(callbackState)},
            {"view", viewCompletenessClassName(view)},
            {"historyShape", historyShapeClassName(shape)},
            {"historyRisk", historyRiskClassName(risk)},
            {"behavior", wildPointerBehaviorClassName(behavior)},
            {"wildLike", wm.wildLike},
            {"metrics", historyMetricsJson(m, shape, risk, behavior)},
            {"wildPointerMetrics", wildPointerMetricsJson(wm)},
            {"paperWildness", paperWildnessJson(paper)},
            {"semanticMediation", semanticMediationJson(mediation)},
            {"stableParamClassification",
             stableClassificationJson(
                 "param", fs.name + ".$" + std::to_string(i),
                 wildPointerBehaviorClassName(behavior), mediation,
                 historyRiskClassName(risk),
                 pointerUseEvidenceSourceKind(evidence), pd)},
            {"behaviorEvidence", behaviorEvidenceJson(evidence, uses)}});
      }
    }

    return arr;
  }

  json::Array emitFunctionBehaviorClassificationsJson() const {
    json::Array arr;

    for (const auto &entry : functionSummaries) {
      const FunctionDecl *fd = entry.first;
      const FunctionSummary &fs = entry.second;
      auto useIt = findByFunctionIdentity(functionParamUseSummaries, fd);

      FunctionBehaviorEvidence fe;
      PointerUseEvidenceMetrics functionEvidence;
      json::Array evidence;

      for (size_t i = 0; i < fs.params.size(); ++i) {
        std::optional<std::string> base = fs.params[i].declaredType.text;
        const std::vector<PointerUseRecord> *uses = nullptr;
        if (useIt != functionParamUseSummaries.end() &&
            i < useIt->second.size())
          uses = &useIt->second[i];

        std::optional<TypeAtom> baseAtom = std::nullopt;
        if (fd && i < fd->getNumParams())
          baseAtom = typeAtomFromQualType(fd->getParamDecl(i)->getType());

        HistoryMetrics m =
            computeHistoryMetrics(fs.params[i].obsSummary, base, uses, baseAtom);
        WildPointerBehaviorMetrics wm =
            computeWildPointerBehaviorMetrics(m, uses);
        CallbackMediationState callbackState =
            callbackMediationStateForFunction(fd, m, uses);
        WildPointerBehaviorClass behavior =
            classifyWildPointerBehavior(m, uses, callbackState);
        PointerUseEvidenceMetrics sourceEvidence = computePointerUseEvidenceMetrics(uses);
        HistoryRiskClass risk = classifyHistoryRisk(m, base);
        PaperWildnessSummary paper =
            computePaperWildnessSummary(m, wm, risk, behavior);
        SemanticMediationSummary mediation =
            computeSemanticMediationSummary(uses, paper, behavior, callbackState);
        FunctionParameterRoleClass role =
            classifyFunctionParameterRole(fs.params[i].declaredType, m,
                                          callbackState);

        accumulateFunctionBehaviorEvidence(fe, behavior, role);

        if (wm.wildLike || fs.params[i].obsSummary ||
            role != FunctionParameterRoleClass::OrdinaryParameter) {
          mergePointerUseEvidenceMetrics(functionEvidence, sourceEvidence);
          evidence.push_back(json::Object{
              {"paramIndex", static_cast<int64_t>(i)},
              {"role", functionParameterRoleClassName(role)},
              {"callbackMediationState", callbackMediationStateName(callbackState)},
              {"behavior", wildPointerBehaviorClassName(behavior)},
              {"paperWildness", paperWildnessJson(paper)},
              {"semanticMediation", semanticMediationJson(mediation)},
              {"summary", historySummaryJson(fs.params[i].obsSummary)},
              {"behaviorEvidence", behaviorEvidenceJson(sourceEvidence, uses)}});
        }
      }

      FunctionBehaviorClass fc = classifyFunctionBehavior(fe);
      if (fc == FunctionBehaviorClass::OrdinaryFunction && evidence.empty())
        continue;

      arr.push_back(json::Object{
          {"function", fs.name},
          {"identity", functionIdentityJson(fd, fs)},
          {"class", functionBehaviorClassName(fc)},
          {"classificationEvidenceSourceKind", pointerUseEvidenceSourceKind(functionEvidence)},
          {"classificationEvidenceSources", stringSetJson(functionEvidence.sources)},
          {"classificationEvidence", functionBehaviorClassificationEvidenceJson(functionEvidence)},
          {"evidenceFlags",
           json::Object{{"callbackProvider", fe.hasCallbackProvider},
                        {"callbackDependent", fe.hasCallbackDependent},
                        {"fieldCallbackProvider", fe.hasFieldCallbackProvider},
                        {"guardedFieldCallbackSelection",
                         fe.hasGuardedFieldCallbackSelection},
                        {"resolvedCallbackMediation",
                         fe.hasResolvedCallbackMediation},
                        {"bytewise", fe.hasBytewise},
                        {"typeErasure", fe.hasTypeErasure},
                        {"concreteSpecializer", fe.hasConcreteSpecializer},
                        {"reinterpretingWrite", fe.hasReinterpretingWrite},
                        {"byteWrite", fe.hasByteWrite},
                        {"concreteWrite", fe.hasConcreteWrite},
                        {"taggedUnionLike", fe.hasTaggedUnionLike},
                        {"multiTargetReinterpretation",
                         fe.hasMultiTargetReinterpretation},
                        {"unsafeReinterpretation",
                         fe.hasUnsafeReinterpretation}}},
          {"evidence", std::move(evidence)}});
    }

    return arr;
  }

  bool sourceSpanLess(const SourceSpan &a, const SourceSpan &b) const {
    if (a.file != b.file)
      return a.file < b.file;
    if (a.line != b.line)
      return a.line < b.line;
    return a.column < b.column;
  }

  static const char *obsKindNameForSummary(ObsKind k) {
    switch (k) {
    case ObsKind::AsType:
      return "asType";
    case ObsKind::PtrArith:
      return "ptrarith";
    case ObsKind::Join:
      return "join";
    case ObsKind::ParamRef:
      return "paramRef";
    case ObsKind::ReturnRef:
      return "returnRef";
    case ObsKind::HOFParamRef:
      return "higherOrderParamRef";
    case ObsKind::FieldRef:
      return "fieldRef";
    case ObsKind::Seq:
      return "seq";
    case ObsKind::Parallel:
      return "parallel";
    case ObsKind::CallWrap:
      return "callWrap";
    case ObsKind::Unknown:
      return "unknown";
    }
    return "unknown";
  }

  std::string readableFunctionSignature(const FunctionDecl *fd,
                                        const FunctionSummary &fs) const {
    std::string out;
    llvm::raw_string_ostream os(out);

    os << fs.ret.declaredType.text << " " << fs.name << "(";
    for (size_t i = 0; i < fs.params.size(); ++i) {
      if (i)
        os << ", ";
      os << fs.params[i].declaredType.text;

      std::string paramName;
      if (fd && i < fd->getNumParams())
        paramName = fd->getParamDecl(static_cast<unsigned>(i))->getNameAsString();

      if (!paramName.empty())
        os << " " << paramName;
      else
        os << " $" << i;
    }
    os << ")";
    os.flush();
    return out;
  }

  std::string readableFunctionStory(
      const FunctionDecl *fd,
      const FunctionSummary &fs,
      const std::vector<std::string> &paramStories) const {
    std::string out;
    llvm::raw_string_ostream os(out);

    os << readableFunctionSignature(fd, fs);
    if (!paramStories.empty()) {
      os << "; ";
      for (size_t i = 0; i < paramStories.size(); ++i) {
        if (i)
          os << "; ";
        os << paramStories[i];
      }
    }

    if (fs.ret.obsSummary) {
      os << "; return: " << ObsFormatter::render(fs.ret.obsSummary);
      if (fs.ret.mayAliasParam && fs.ret.aliasedParamIndex)
        os << " (aliases $" << *fs.ret.aliasedParamIndex << ")";
    } else if (fs.ret.mayAliasParam && fs.ret.aliasedParamIndex) {
      os << "; return aliases $" << *fs.ret.aliasedParamIndex;
    }

    os.flush();
    return out;
  }

  json::Object compactPointerUseJson(const PointerUseRecord &u) const {
    json::Object obj{
        {"kind", pointerUseKindName(u.kind)},
        {"pointerType", u.pointerType},
        {"detail", u.detail},
        {"location", sourceSpanJson(u.span)},
        {"operationSiteSpan", sourceSpanJson(operationSiteSpanForPointerUse(u))},
        {"operationLocalGuardOrigin", operationLocalGuardOriginForPointerUse(u)},
        {"attachPath",
         u.attachPath ? ObsFormatter::render(u.attachPath) : std::string("<id>")}};

    if (u.accessType)
      obj["accessType"] = *u.accessType;
    else
      obj["accessType"] = json::Value(nullptr);

    if (u.guard)
      obj["guard"] = u.guard->text;
    else
      obj["guard"] = json::Value(nullptr);

    if (u.operationLocalGuardKnown && u.operationLocalGuard)
      obj["operationLocalGuard"] = u.operationLocalGuard->text;
    else
      obj["operationLocalGuard"] = json::Value(nullptr);

    obj["provenance"] = pointerUseProvenanceJson(u.provenance);

    return obj;
  }

  json::Object compactMetricsJson(const HistoryMetrics &m,
                                  const WildPointerBehaviorMetrics &wm) const {
    return json::Object{
        {"seqDepth", static_cast<int64_t>(m.seqDepth)},
        {"numDistinctTypes", static_cast<int64_t>(m.numDistinctTypes)},
        {"numPointerTypes", static_cast<int64_t>(m.numPointerTypes)},
        {"numNonVoidPointerTypes",
         static_cast<int64_t>(m.numNonVoidPointerTypes)},
        {"pointerTypes", stringSetJson(m.pointerTypes)},
        {"nonVoidPointerTypes", stringSetJson(m.nonVoidPointerTypes)},
        {"derefTypes", stringSetJson(wm.derefTypes)},
        {"writeDerefTypes", stringSetJson(wm.writeDerefTypes)},
        {"flags",
         json::Object{{"void", m.hasVoid},
                      {"charPtr", m.hasCharPtr},
                      {"ptrArith", m.hasPointerArithmetic},
                      {"intToPtr", m.hasIntToPtr},
                      {"ptrToInt", m.hasPtrToInt},
                      {"externalSink", m.hasExternalSink},
                      {"byteWrite", wm.hasByteViewWrite},
                      {"concreteWrite", wm.hasConcreteWrite},
                      {"multiTypeWrite", wm.hasMultiTypeWrite},
                      {"higherOrder", wm.hasHigherOrderForwarding}}}};
  }

  json::Object readableFunctionSummaryJson(const FunctionDecl *fd,
                                           const FunctionSummary &fs) const {
    auto useIt = findByFunctionIdentity(functionParamUseSummaries, fd);

    FunctionBehaviorEvidence fe;
    json::Array params;
    std::vector<std::string> paramStories;

    for (size_t i = 0; i < fs.params.size(); ++i) {
      const auto &p = fs.params[i];

      const std::vector<PointerUseRecord> *uses = nullptr;
      if (useIt != functionParamUseSummaries.end() && i < useIt->second.size())
        uses = &useIt->second[i];

      std::optional<TypeAtom> baseAtom = std::nullopt;
      std::string paramName;
      if (fd && i < fd->getNumParams()) {
        const ParmVarDecl *pd = fd->getParamDecl(static_cast<unsigned>(i));
        baseAtom = typeAtomFromQualType(pd->getType());
        paramName = pd->getNameAsString();
      }

      HistoryMetrics m =
          computeHistoryMetrics(p.obsSummary,
                                std::optional<std::string>(p.declaredType.text),
                                uses, baseAtom);
      HistoryShapeClass shape = classifyHistoryShape(m);
      HistoryRiskClass risk = classifyHistoryRisk(m, p.declaredType.text);
      WildPointerBehaviorMetrics wm =
          computeWildPointerBehaviorMetrics(m, uses);
      CallbackMediationState callbackState =
          callbackMediationStateForFunction(fd, m, uses);
      WildPointerBehaviorClass behavior =
          classifyWildPointerBehavior(m, uses, callbackState);
      PaperWildnessSummary paper =
          computePaperWildnessSummary(m, wm, risk, behavior);
      SemanticMediationSummary mediation =
          computeSemanticMediationSummary(uses, paper, behavior, callbackState);
      ViewCompletenessClass view =
          classifyViewCompleteness(m, wm, true, false);
      FunctionParameterRoleClass role =
          classifyFunctionParameterRole(p.declaredType, m, callbackState);
      accumulateFunctionBehaviorEvidence(fe, behavior, role);

      std::string renderedSummary =
          p.obsSummary ? ObsFormatter::render(p.obsSummary) : std::string("<none>");

      std::string paramStory;
      llvm::raw_string_ostream ps(paramStory);
      ps << "$" << i;
      if (!paramName.empty())
        ps << " " << paramName;
      ps << ": " << p.declaredType.text;
      if (p.obsSummary)
        ps << " => " << renderedSummary;
      ps << " [" << wildPointerBehaviorClassName(behavior) << "]";
      ps.flush();
      paramStories.push_back(paramStory);

      json::Array compactUses;
      if (uses) {
        for (const auto &u : *uses)
          compactUses.push_back(compactPointerUseJson(u));
      }
      json::Array compactGroups = pointerUseOperationGroupsJson(uses);
      json::Array semanticGroups = semanticPointerOperationGroupsJson(uses);

      json::Object paramObj{
          {"index", static_cast<int64_t>(i)},
          {"name", paramName},
          {"declaredType", p.declaredType.text},
          {"declaredTypeKey", p.declaredType.semanticKey()},
          {"summary", renderedSummary},
          {"role", functionParameterRoleClassName(role)},
          {"callbackMediationState", callbackMediationStateName(callbackState)},
          {"view", viewCompletenessClassName(view)},
          {"historyShape", historyShapeClassName(shape)},
          {"historyRisk", historyRiskClassName(risk)},
          {"behavior", wildPointerBehaviorClassName(behavior)},
          {"wildLike", wm.wildLike},
          {"paperWildness", paperWildnessJson(paper)},
          {"semanticMediation", semanticMediationJson(mediation)},
          {"metrics", compactMetricsJson(m, wm)},
          {"pointerUses", std::move(compactUses)},
          {"pointerUseGroups", std::move(compactGroups)},
          {"semanticPointerUseGroups", std::move(semanticGroups)}};

      if (p.obsSummary)
        paramObj["summaryIrKind"] = obsKindNameForSummary(p.obsSummary->kind);
      else
        paramObj["summaryIrKind"] = json::Value(nullptr);

      params.push_back(std::move(paramObj));
    }

    FunctionBehaviorClass functionClass = classifyFunctionBehavior(fe);

    json::Object retObj{{"declaredType", fs.ret.declaredType.text},
                        {"declaredTypeKey", fs.ret.declaredType.semanticKey()},
                        {"summary", fs.ret.obsSummary
                                        ? ObsFormatter::render(fs.ret.obsSummary)
                                        : std::string("<none>")},
                        {"mayAliasParam", fs.ret.mayAliasParam},
                        {"aliasedParamIndex",
                         (fs.ret.mayAliasParam && fs.ret.aliasedParamIndex)
                             ? json::Value(static_cast<int64_t>(*fs.ret.aliasedParamIndex))
                             : json::Value(nullptr)}};

    if (fs.ret.obsSummary)
      retObj["summaryIrKind"] = obsKindNameForSummary(fs.ret.obsSummary->kind);
    else
      retObj["summaryIrKind"] = json::Value(nullptr);

    SourceSpan loc = fd ? sourceSpan(fd->getLocation()) : SourceSpan{};

    return json::Object{
        {"function", fs.name},
        {"signature", readableFunctionSignature(fd, fs)},
        {"location", sourceSpanJson(loc)},
        {"functionBehavior", functionBehaviorClassName(functionClass)},
        {"story", readableFunctionStory(fd, fs, paramStories)},
        {"params", std::move(params)},
        {"return", std::move(retObj)},
        {"coverage", functionCoverageJson(fs.name)},
        {"detailRef", std::string("functionSummaryDetails[") + fs.name + "]"}};
  }

  json::Array emitFlowRecordsSummaryJson() const {
    // Keep this section close to the first part of the text output.  The
    // older emitJson() name is retained for the --json mode, but C1 summaries
    // use a more descriptive top-level key: flowRecords.
    return emitJson();
  }

  json::Array emitReadableFunctionSummariesJson() const {
    json::Array arr;

    std::vector<const FunctionDecl *> fds;
    fds.reserve(functionSummaries.size());
    for (const auto &entry : functionSummaries)
      fds.push_back(entry.first);

    std::sort(fds.begin(), fds.end(),
              [this](const FunctionDecl *a, const FunctionDecl *b) {
                SourceSpan sa = a ? sourceSpan(a->getLocation()) : SourceSpan{};
                SourceSpan sb = b ? sourceSpan(b->getLocation()) : SourceSpan{};

                if (sourceSpanLess(sa, sb))
                  return true;
                if (sourceSpanLess(sb, sa))
                  return false;

                std::string an = a ? a->getQualifiedNameAsString() : std::string();
                std::string bn = b ? b->getQualifiedNameAsString() : std::string();
                return an < bn;
              });

    for (const FunctionDecl *fd : fds) {
      auto it = functionSummaries.find(fd);
      if (it != functionSummaries.end())
        arr.push_back(readableFunctionSummaryJson(it->first, it->second));
    }

    return arr;
  }

