  json::Array emitPaperVoidPointerUsageFingerprintsJson() const {
    json::Array arr;
    for (const auto &entry : paperVoidPointerUsageFacts) {
      const EntityKey &entity = entry.first;
      const PaperVoidPointerUsageFacts &facts = entry.second;
      json::Object inventory = paperDeclaredPointerInventoryJson(entity);
      const std::string status =
          jsonStringOrEmpty(inventory, "classificationStatus");
      const FunctionDecl *fd = paperEnclosingFunction(entity);
      json::Object functionObj{
          {"qualifiedName", fd ? fd->getQualifiedNameAsString() : std::string()},
          {"signatureKey", fd ? functionSignatureKey(fd) : std::string()}};
      const PaperObservedNoFinalHistoryFacts noFinalFacts =
          computePaperObservedNoFinalHistoryFacts(entity, facts);
      arr.push_back(json::Object{
          {"usageId", "void-pointer-usage-v1|" + paperSubjectStableId(entity)},
          {"subjectId", paperSubjectStableId(entity)},
          {"declarationId", paperDeclaredPointerDeclarationId(entity)},
          {"subjectKind", paperDeclaredInventoryKind(entity.decl)},
          {"entity", renderEntity(entity)},
          {"location", sourceSpanJson(paperDeclaredPointerPrevalenceSpan(entity))},
          {"function", std::move(functionObj)},
          {"declaredType", paperDeclaredTypeJson(entity)},
          {"subjectFactEmitted", jsonBoolOrFalse(inventory, "subjectFactEmitted")},
          {"hasFinalHistory", jsonBoolOrFalse(inventory, "hasFinalHistory")},
          {"classificationStatus", status},
          {"noFactPrimaryReason", paperNoFactPrimaryReason(status, facts)},
          {"genericCandidateConfidence",
           paperGenericCandidateConfidence(status, facts)},
          {"observedNoFinalHistory",
           paperObservedNoFinalHistoryJson(status, noFinalFacts)},
          {"usageFlags", paperVoidPointerUsageFlagsJson(facts)},
          {"evidenceKinds", paperStringArray(facts.evidenceKinds)},
          {"callSites", paperStringArray(facts.callSites)}});
    }
    return arr;
  }

  json::Array emitPaperAllocationOriginDerivedAliasUsesJson() const {
    json::Array arr;
    for (const auto &entry : paperAllocationDerivedAliasFacts) {
      const PaperAllocationDerivedAliasKey &key = entry.first;
      const PaperAllocationDerivedAliasFacts &aliasFacts = entry.second;
      auto originIt = paperAllocationOrigins.find(key.origin);
      if (originIt == paperAllocationOrigins.end() || !key.alias)
        continue;
      const PaperAllocationOriginFacts &originFacts = originIt->second;
      const FunctionDecl *originFunction = paperEnclosingFunction(key.origin);
      const FunctionDecl *aliasFunction = paperEnclosingFunction(
          entityOfValueDecl(key.alias));
      const SourceSpan originSpan = paperDeclaredPointerPrevalenceSpan(key.origin);
      const SourceSpan aliasSpan = sourceSpan(key.alias->getLocation());
      const std::string originSubjectId = paperSubjectStableId(key.origin);
      const std::string aliasDeclId = paperCallbackOwnerDeclarationId(key.alias);
      std::ostringstream reportId;
      reportId << "allocation-alias-use-v1|" << originSubjectId << "|"
               << aliasDeclId;
      json::Object originFunctionObj{
          {"qualifiedName",
           originFunction ? originFunction->getQualifiedNameAsString()
                          : std::string()},
          {"signatureKey",
           originFunction ? functionSignatureKey(originFunction) : std::string()}};
      json::Object aliasFunctionObj{
          {"qualifiedName",
           aliasFunction ? aliasFunction->getQualifiedNameAsString()
                         : std::string()},
          {"signatureKey",
           aliasFunction ? functionSignatureKey(aliasFunction) : std::string()}};
      json::Object originDeclaredType = paperDeclaredTypeJson(key.origin);
      json::Object aliasDeclaredType{
          {"text", typeToString(key.alias->getType())},
          {"canonicalText", typeToString(key.alias->getType().getCanonicalType())},
          {"outerPointerKind", paperOuterPointerKind(key.alias->getType())}};
      arr.push_back(json::Object{
          {"reportId", reportId.str()},
          {"originSubjectId", originSubjectId},
          {"originDeclarationId", paperDeclaredPointerDeclarationId(key.origin)},
          {"originEntity", renderEntity(key.origin)},
          {"originLocation", sourceSpanJson(originSpan)},
          {"originFunction", std::move(originFunctionObj)},
          {"originDeclaredType", std::move(originDeclaredType)},
          {"allocatorFamilies", paperStringArray(originFacts.allocatorFamilies)},
          {"allocatorFunctions", paperStringArray(originFacts.allocatorFunctions)},
          {"allocationCallSites", paperStringArray(originFacts.allocationCallSites)},
          {"originBindingKinds", paperStringArray(originFacts.originBindingKinds)},
          {"aliasDeclarationId", aliasDeclId},
          {"aliasEntity", key.alias->getQualifiedNameAsString()},
          {"aliasName", key.alias->getNameAsString()},
          {"aliasLocation", sourceSpanJson(aliasSpan)},
          {"aliasFunction", std::move(aliasFunctionObj)},
          {"aliasDeclaredType", std::move(aliasDeclaredType)},
          {"derivationKinds", paperStringArray(aliasFacts.derivationKinds)},
          {"derivationSites", paperStringArray(aliasFacts.derivationSites)},
          {"mayAlias", true},
          {"usageFlags", paperAllocationAliasUsageFlagsJson(aliasFacts)},
          {"evidenceKinds", paperStringArray(aliasFacts.evidenceKinds)},
          {"useSites", paperStringArray(aliasFacts.useSites)}});
    }
    return arr;
  }

  json::Array emitPaperNestedCallbackSlotRelationsJson() const {
    json::Array arr;
    for (const auto &entry : paperCallbackSlotRelations) {
      const PaperCallbackSlotRelationFact &slot = entry.second;
      json::Array correlated;
      for (const EntityKey &entity : slot.correlatedDirectSubjects) {
        correlated.push_back(json::Object{
            {"subjectId", paperSubjectStableId(entity)},
            {"entity", renderEntity(entity)},
            {"declarationId", paperDeclaredPointerDeclarationId(entity)}});
      }
      json::Object ownerFunction{
          {"qualifiedName", slot.ownerFunctionQualifiedName},
          {"signatureKey", slot.ownerFunctionSignatureKey}};
      arr.push_back(json::Object{
          {"slotId", slot.slotId},
          {"ownerDeclarationId", slot.ownerDeclarationId},
          {"ownerDeclarationKind", slot.ownerDeclarationKind},
          {"ownerName", slot.ownerName},
          {"ownerFunction", std::move(ownerFunction)},
          {"ownerParameterIndex",
           slot.ownerParameterIndex
               ? json::Value(static_cast<int64_t>(*slot.ownerParameterIndex))
               : json::Value(nullptr)},
          {"relationVariable", slot.relationVariable},
          {"callbackRole", slot.callbackRole},
          {"positionKind", slot.positionKind},
          {"positionPath", slot.positionPath},
          {"callbackArgumentIndex",
           slot.callbackArgumentIndex
               ? json::Value(static_cast<int64_t>(*slot.callbackArgumentIndex))
               : json::Value(nullptr)},
          {"declaredType", slot.declaredType},
          {"canonicalType", slot.canonicalType},
          {"eligibleForRelationalClassification",
           slot.eligibleForRelationalClassification},
          {"ownerDefinitionAvailable", slot.ownerDefinitionAvailable},
          {"relationalClassificationScope",
           slot.relationalClassificationScope},
          {"eligibilityExclusionReason",
           slot.eligibilityExclusionReason},
          {"correlatedDirectSubjects", std::move(correlated)},
          {"correlationEvidence", paperStringArray(slot.correlationEvidence)},
          {"callSites", paperStringArray(slot.callSites)},
          {"invocation",
           json::Object{{"invoked", slot.invoked},
                        {"hasKnownTarget", slot.hasKnownTarget},
                        {"hasUnresolvedTarget", slot.hasUnresolvedTarget}}}});
    }
    return arr;
  }

  json::Object emitTUPaperFactsJsonObject(
      const std::string &configurationId = std::string(),
      const std::string &compileCommandHash = std::string()) const {
    json::Array subjects = emitPaperSubjectFactsJson();
    json::Array callbacks = emitPaperCallbackUseRecordsJson();
    json::Array declaredInventory = emitPaperDeclaredPointerInventoryJson();
    json::Array nestedCallbackSlots = emitPaperNestedCallbackSlotRelationsJson();
    json::Array voidPointerUsageFingerprints =
        emitPaperVoidPointerUsageFingerprintsJson();
    json::Array allocationOriginDerivedAliasUses =
        emitPaperAllocationOriginDerivedAliasUsesJson();
    int64_t withFinalHistory = 0;
    int64_t eligibleDataPointerRows = 0;
    int64_t directVoidPointerInventoryRows = 0;
    int64_t eligibleVoidPointerRows = 0;
    int64_t excludedUnavailableApiVoidPointerRows = 0;
    int64_t eligibleVoidPointerSubjectFacts = 0;
    int64_t eligibleVoidPointerFinalHistory = 0;
    int64_t eligibleVoidPointerClassified = 0;
    int64_t eligibleVoidPointerNoObservedFacts = 0;
    int64_t finalHistoryWithoutSubjectRow = 0;
    int64_t eligibleNestedCallbackSlots = 0;
    int64_t excludedUnavailableApiNestedCallbackSlots = 0;
    for (const json::Value &value : subjects) {
      const json::Object *obj = value.getAsObject();
      if (obj && jsonBoolOrFalse(*obj, "hasFinalHistory"))
        ++withFinalHistory;
    }
    for (const json::Value &value : declaredInventory) {
      const json::Object *obj = value.getAsObject();
      if (!obj)
        continue;
      const bool eligible =
          jsonBoolOrFalse(*obj, "eligibleForCastHistoryClassification");
      const bool subjectFact = jsonBoolOrFalse(*obj, "subjectFactEmitted");
      const bool finalHistory = jsonBoolOrFalse(*obj, "hasFinalHistory");
      const std::string status = jsonStringOrEmpty(*obj, "classificationStatus");
      const json::Object *declared = obj->getObject("declaredType");
      const std::string outerKind =
          declared ? jsonStringOrEmpty(*declared, "outerPointerKind")
                   : std::string();
      if (eligible)
        ++eligibleDataPointerRows;
      if (outerKind != "void-data-pointer")
        continue;
      ++directVoidPointerInventoryRows;
      if (!eligible) {
        if (status == "out-of-scope-unavailable-api-parameter")
          ++excludedUnavailableApiVoidPointerRows;
        continue;
      }
      ++eligibleVoidPointerRows;
      eligibleVoidPointerSubjectFacts += subjectFact;
      eligibleVoidPointerFinalHistory += finalHistory;
      eligibleVoidPointerClassified += status == "classified";
      eligibleVoidPointerNoObservedFacts +=
          status == "declared-no-observed-facts";
      finalHistoryWithoutSubjectRow +=
          status == "final-history-not-emitted";
    }
    for (const json::Value &value : nestedCallbackSlots) {
      const json::Object *obj = value.getAsObject();
      if (!obj)
        continue;
      if (jsonBoolOrFalse(*obj, "eligibleForRelationalClassification"))
        ++eligibleNestedCallbackSlots;
      else if (jsonStringOrEmpty(*obj, "eligibilityExclusionReason") ==
               "unavailable-owner-function-body")
        ++excludedUnavailableApiNestedCallbackSlots;
    }

    return json::Object{
        {"schemaVersion", static_cast<int64_t>(9)},
        {"schemaName", "cast-history-tu-paper-facts"},
        {"toolVersion", "cast-history-dev"},
        {"tu",
         json::Object{{"sourceFile", mainFileNameForSummary()},
                      {"configurationId", configurationId},
                      {"compileCommandHash", compileCommandHash}}},
        {"coverage",
         json::Object{{"subjectRows", static_cast<int64_t>(subjects.size())},
                      {"subjectsWithFinalHistory", withFinalHistory},
                      {"callbackUseRecords", static_cast<int64_t>(callbacks.size())},
                      {"nestedCallbackSlotRelations",
                       static_cast<int64_t>(nestedCallbackSlots.size())},
                      {"eligibleNestedCallbackSlotRelations",
                       eligibleNestedCallbackSlots},
                      {"excludedUnavailableApiNestedCallbackSlots",
                       excludedUnavailableApiNestedCallbackSlots},
                      {"voidPointerUsageFingerprints",
                       static_cast<int64_t>(voidPointerUsageFingerprints.size())},
                      {"allocationOriginDerivedAliasUses",
                       static_cast<int64_t>(allocationOriginDerivedAliasUses.size())},
                      {"nestedCallbackSlotRelationModel",
                       "callback-slot-relations-v2-definition-availability"},
                      {"voidPointerUsageFingerprintModel",
                       "eligible-direct-void-pointer-usage-v1"},
                      {"observedNoFinalHistoryPatternModel",
                       "retained-pointer-use-and-syntactic-usage-v1"},
                      {"allocationOriginDerivedAliasModel",
                       "recognized-allocator-origin-and-may-derived-alias-use-v1"},
                      {"arrayIndexDirectionModel",
                       "read-write-readwrite-with-legacy-ambiguous-fallback"},
                      {"declaredOuterPointerKindModel",
                       "clang-qualtype-outer-pointer-kind-v1"},
                      {"callbackMediationModel",
                       "callback-mediation-state-v1"},
                      {"fieldStorageClassificationModel",
                       "resolved-instance-field-storage-v1"},
                      {"declaredPointerInventoryModel",
                       "project-owned-local-parameter-direct-pointer-definition-availability-v3"},
                      {"declaredPointerInventoryScope",
                       paperFactsProjectRoot.empty()
                           ? "main-tu-fallback-v1"
                           : "project-root-v1"},
                      {"declaredPointerInventoryScopeComplete",
                       !paperFactsProjectRoot.empty()},
                      {"declaredPointerInventoryRows",
                       static_cast<int64_t>(declaredInventory.size())},
                      {"declaredDirectVoidPointerInventoryRows",
                       directVoidPointerInventoryRows},
                      {"declaredEligibleDataPointerRows",
                       eligibleDataPointerRows},
                      {"declaredEligibleVoidPointerRows",
                       eligibleVoidPointerRows},
                      {"declaredExcludedUnavailableApiVoidPointerRows",
                       excludedUnavailableApiVoidPointerRows},
                      {"declaredEligibleVoidPointerSubjectFacts",
                       eligibleVoidPointerSubjectFacts},
                      {"declaredEligibleVoidPointerFinalHistory",
                       eligibleVoidPointerFinalHistory},
                      {"declaredEligibleVoidPointerClassified",
                       eligibleVoidPointerClassified},
                      {"declaredEligibleVoidPointerNoObservedFacts",
                       eligibleVoidPointerNoObservedFacts},
                      {"finalHistoryWithoutSubjectRow",
                       finalHistoryWithoutSubjectRow}}},
        {"subjects", std::move(subjects)},
        {"declaredPointerInventory", std::move(declaredInventory)},
        {"callbackUseRecords", std::move(callbacks)},
        {"nestedCallbackSlotRelations", std::move(nestedCallbackSlots)},
        {"voidPointerUsageFingerprints", std::move(voidPointerUsageFingerprints)},
        {"allocationOriginDerivedAliasUses",
         std::move(allocationOriginDerivedAliasUses)}};
  }

  void emitTUPaperFactsJson(
      raw_ostream &os, const std::string &configurationId = std::string(),
      const std::string &compileCommandHash = std::string()) const {
    json::Value v(emitTUPaperFactsJsonObject(configurationId,
                                              compileCommandHash));
    os << llvm::formatv("{0:2}\n", v);
  }

  json::Array emitFeatureDiagnosticsJson() const {
    json::Array arr;

    std::vector<const FeatureSupportRecord *> records;
    records.reserve(featureSupportRecords.size());
    for (const auto &rec : featureSupportRecords)
      records.push_back(&rec);

    std::sort(records.begin(), records.end(),
              [this](const FeatureSupportRecord *a,
                     const FeatureSupportRecord *b) {
                if (sourceSpanLess(a->span, b->span))
                  return true;
                if (sourceSpanLess(b->span, a->span))
                  return false;
                if (a->functionName != b->functionName)
                  return a->functionName < b->functionName;
                return a->feature < b->feature;
              });

    for (const FeatureSupportRecord *rec : records) {
      arr.push_back(json::Object{
          {"severity", featureSupportSeverityName(rec->severity)},
          {"feature", rec->feature},
          {"function", rec->functionName},
          {"reason", rec->reason},
          {"location", sourceSpanJson(rec->span)}});
    }
    return arr;
  }



  json::Array emitSummaryParamTransferEdgesJson(bool linkFormat = false) const {
    // C4H: project-level parameter-transfer facts.
    //
    // summaryDependencyEdges tell the index builder that caller depends on
    // callee.  These transfer facts additionally say which caller parameter
    // reaches which callee formal, and what local path was already taken by
    // the actual argument.  The project-level solver can then propagate a
    // solved callee parameter summary to callers without re-running Clang.
    //
    // C6g5w1 deliberately adds only diagnostics metadata.  It neither changes
    // summary composition nor participates in equality, SCC scheduling, or
    // import lookup.  The metadata identifies source-defined candidate branch
    // families/arms on the normal transfer edge channel so the next patch can
    // prove transport before enabling any branch-aware behavior.
    struct BranchFamilyArmDraft {
      std::string id;
      std::string kind;
      std::string actualPath;
      std::string guardText;
      std::string originSourceEntity;
      SourceSpan originSpan;
    };

    struct TransferDraft {
      const NamedCallEdge *edge = nullptr;
      unsigned calleeParamIndex = 0;
      unsigned callerParamIndex = 0;
      // Own the immutable call-site alternative so diagnostics-only
      // expansion of a guarded Join cannot leave a pointer into temporary
      // normalization state.  This type remains private to JSON emission.
      OriginAlternative alt;
      std::string callerQN;
      std::string calleeQN;
      std::string callerSig;
      std::string calleeSig;
      std::string callerNode;
      std::string calleeNode;
      SourceSpan span;
      std::string pathRendered;
      std::string guardText;
      std::string familyId;
      std::string familyKind;
      std::string familyOrigin;
      // C6g5w1c: immutable diagnostics-only key for a later narrow
      // recursive-composition rule.  It is deliberately distinct from
      // familyId: provenance stays source-family-specific, while matching
      // guarded local transformers may share one semantic closure key.
      std::string recursiveClosureKey;
      std::string armId;
      std::string armKind;
      // C6g5w1b: a single ordinary transfer edge can carry several local
      // guarded pointer-arithmetic arm snapshots.  The edge itself is not
      // duplicated: this is diagnostics-only metadata and is intentionally
      // ignored by the solver/import composition path.
      std::vector<BranchFamilyArmDraft> branchArms;
    };

    auto spanKey = [](const SourceSpan &span) {
      return span.file + ":" + std::to_string(span.line) + ":" +
             std::to_string(span.column);
    };
    auto pathKey = [](const OriginAlternative &alt) {
      ObsHistPtr normalized = normalizeObs(alt.pathFromSource);
      std::string rendered = normalized ? ObsFormatter::render(normalized)
                                        : std::string("<identity>");
      return rendered;
    };

    std::vector<TransferDraft> drafts;

    // C6g5w1a: a flow merge can preserve p127-style guarded origins as one
    // top-level ObsKind::Join rather than separate OriginAlternative records.
    // Expand only that diagnostics representation into arm snapshots here.
    // This has no effect on the stored origin state, summary transfer facts,
    // or solver: the generated drafts are used solely to label exported
    // branchFamily/branchArm metadata.
    auto expandGuardedJoinAlternative = [this](const OriginAlternative &alt) {
      std::vector<OriginAlternative> out;
      ObsHistPtr normalized = normalizeObs(alt.pathFromSource);
      if (!normalized || normalized->kind != ObsKind::Join) {
        out.push_back(alt);
        return out;
      }
      for (const ObsAlt &branch : normalized->alts) {
        if (!branch.hist)
          continue;
        OriginAlternative expanded = alt;
        expanded.pathFromSource = normalizeObs(branch.hist);
        expanded.guard = combineGuards(alt.guard, branch.guard);
        out.push_back(std::move(expanded));
      }
      if (out.empty())
        out.push_back(alt);
      return out;
    };

    // C6g5w1b: p127's branch merge intentionally coalesces two same-shaped
    // reaching origins for `q` into one may-origin before the later `g(q, tag)`
    // call.  That keeps normal analysis finite, but it also means
    // originsAtCall alone no longer retains the two guarded ptrarith arms.
    // Recover *only diagnostics metadata* from the source-local AST shape:
    //
    //   if (tag) q = p + c1; else q = p + c2; callee(q, ...);
    //
    // The helper is deliberately narrow.  It recognizes a direct local
    // variable actual, a single surrounding IfStmt with then/else assignments
    // to that exact local, and pointer arithmetic rooted directly at one
    // caller formal.  It does not modify OriginInfo, summaries, solver facts,
    // or ordinary transfer edge multiplicity.
    auto guardedLocalPtrArithArmsForActual =
        [this, &spanKey](const NamedCallEdge &edge,
                         const NamedCallActual &actual,
                         unsigned calleeParamIndex,
                         const std::string &callerNode,
                         const std::string &calleeNode,
                         const SourceSpan &callSpan) {
      struct Candidate {
        const ParmVarDecl *rootParam = nullptr;
        BranchFamilyArmDraft arm;
      };
      std::vector<Candidate> out;
      if (!edge.caller || !edge.call || !actual.expr)
        return out;

      const Expr *actualExpr = actual.expr->IgnoreParenImpCasts();
      const auto *actualRef = dyn_cast<DeclRefExpr>(actualExpr);
      const auto *local = actualRef
                              ? dyn_cast<ValueDecl>(actualRef->getDecl())
                              : nullptr;
      if (!local || isa<ParmVarDecl>(local))
        return out;

      auto directAssignmentToLocal = [this, local](const Stmt *stmt)
          -> const BinaryOperator * {
        if (!stmt)
          return nullptr;
        const auto *assign = dyn_cast<BinaryOperator>(stmt);
        if (!assign || !assign->isAssignmentOp())
          return nullptr;
        const Expr *lhs = assign->getLHS()->IgnoreParenImpCasts();
        const auto *lhsRef = dyn_cast<DeclRefExpr>(lhs);
        if (!lhsRef || lhsRef->getDecl() != local)
          return nullptr;
        const Expr *rhs = assign->getRHS()->IgnoreParenImpCasts();
        const auto *ptrArith = dyn_cast<BinaryOperator>(rhs);
        if (!ptrArith || !pointerOperandOfPointerArithmetic(ptrArith))
          return nullptr;
        return ptrArith;
      };

      auto assignmentInBranch = [&directAssignmentToLocal](const Stmt *root)
          -> const BinaryOperator * {
        if (!root)
          return nullptr;
        if (const auto *direct = directAssignmentToLocal(root))
          return direct;
        if (const auto *compound = dyn_cast<CompoundStmt>(root)) {
          const BinaryOperator *only = nullptr;
          for (const Stmt *child : compound->body()) {
            const BinaryOperator *found = directAssignmentToLocal(child);
            if (!found)
              continue;
            if (only)
              return nullptr; // ambiguous branch write; reject narrowly.
            only = found;
          }
          return only;
        }
        return nullptr;
      };

      std::function<void(const Stmt *)> visit;
      visit = [&](const Stmt *stmt) {
        if (!stmt)
          return;
        const auto *ifStmt = dyn_cast<IfStmt>(stmt);
        if (ifStmt && ifStmt->getThen() && ifStmt->getElse()) {
          const BinaryOperator *thenAssign = assignmentInBranch(ifStmt->getThen());
          const BinaryOperator *elseAssign = assignmentInBranch(ifStmt->getElse());
          if (thenAssign && elseAssign) {
            const Expr *thenPtr = pointerOperandOfPointerArithmetic(thenAssign);
            const Expr *elsePtr = pointerOperandOfPointerArithmetic(elseAssign);
            const auto *thenRef = thenPtr
                                      ? dyn_cast<DeclRefExpr>(
                                            thenPtr->IgnoreParenImpCasts())
                                      : nullptr;
            const auto *elseRef = elsePtr
                                      ? dyn_cast<DeclRefExpr>(
                                            elsePtr->IgnoreParenImpCasts())
                                      : nullptr;
            const auto *thenParam = thenRef
                                        ? dyn_cast<ParmVarDecl>(thenRef->getDecl())
                                        : nullptr;
            const auto *elseParam = elseRef
                                        ? dyn_cast<ParmVarDecl>(elseRef->getDecl())
                                        : nullptr;
            if (thenParam && thenParam == elseParam &&
                paramIndexOfInFunction(edge.caller, thenParam)) {
              const std::string condition = exprToString(ifStmt->getCond());
              if (!condition.empty()) {
                auto makeArm = [&](const BinaryOperator *assign,
                                   const std::string &guard) {
                  TypeAtom ty = typeAtomFromQualType(assign->getType());
                  BranchFamilyArmDraft arm;
                  arm.kind = "guarded-local-ptrarith";
                  arm.actualPath = ObsFormatter::render(mkObsPtrArith(ty));
                  arm.guardText = guard;
                  arm.originSourceEntity = renderEntity(entityOfValueDecl(thenParam));
                  arm.originSpan = sourceSpan(assign->getOperatorLoc());
                  arm.id = "branch-family:guarded-local-ptrarith:" +
                           callerNode + ".$" +
                           std::to_string(*paramIndexOfInFunction(edge.caller,
                                                                    thenParam)) +
                           "->" + calleeNode + ".$" +
                           std::to_string(calleeParamIndex) + "@" +
                           spanKey(callSpan) + ":arm@" +
                           spanKey(arm.originSpan) + ":path=" +
                           arm.actualPath + ":guard=" + arm.guardText;
                  out.push_back(Candidate{thenParam, std::move(arm)});
                };
                makeArm(thenAssign, condition);
                makeArm(elseAssign, "!(" + condition + ")");
              }
            }
          }
        }
        for (const Stmt *child : stmt->children())
          visit(child);
      };

      visit(edge.caller->getBody());
      return out;
    };

    // C6g5w1c: branchFamilyId is intentionally source/provenance-specific.
    // Recursive closure needs a second key that recognizes the same guarded
    // local transformer at different functions in one recursive SCC.  Keep
    // the construction local and canonical: no function name, call location,
    // or arm source span participates; formal position, source-formal type,
    // and sorted guard/path arm signatures do.
    auto guardedLocalPtrArithRecursiveClosureKey =
        [this](unsigned rootParamIndex, const ParmVarDecl *rootParam,
               const std::vector<BranchFamilyArmDraft> &arms) {
      std::set<std::string> canonicalArms;
      for (const BranchFamilyArmDraft &arm : arms) {
        const std::string guard = arm.guardText.empty()
                                      ? std::string("<unguarded>")
                                      : arm.guardText;
        canonicalArms.insert(guard + "=>" + arm.actualPath);
      }
      TypeAtom rootType =
          rootParam ? typeAtomFromQualType(rootParam->getType()) : TypeAtom{};
      std::ostringstream os;
      os << "recursive-closure:guarded-local-ptrarith:formal=$"
         << rootParamIndex << ":type="
         << (rootType.text.empty() ? std::string("<unknown>") : rootType.text)
         << ":arms=[";
      bool first = true;
      for (const std::string &arm : canonicalArms) {
        if (!first)
          os << ",";
        first = false;
        os << arm;
      }
      os << "]";
      return os.str();
    };

    for (const NamedCallEdge &edge : namedCallEdges) {
      if (!edge.caller || !edge.callee)
        continue;

      std::string callerQN = functionQualifiedNameForDependency(edge.caller);
      std::string calleeQN = functionQualifiedNameForDependency(edge.callee);
      std::string callerSig = functionSignatureKey(edge.caller);
      std::string calleeSig = functionSignatureKey(edge.callee);
      std::string callerNode = callerQN;
      if (!callerSig.empty())
        callerNode += "::" + callerSig;
      std::string calleeNode = calleeQN;
      if (!calleeSig.empty())
        calleeNode += "::" + calleeSig;
      const SourceSpan callSpan = sourceSpan(edge.loc);

      for (unsigned calleeParamIdx = 0;
           calleeParamIdx < edge.actuals.size(); ++calleeParamIdx) {
        const NamedCallActual &actual = edge.actuals[calleeParamIdx];
        for (const OriginAlternative &originalAlt : actual.originsAtCall) {
          if (originalAlt.source.kind != EntityKey::Kind::ValueDeclEntity ||
              !originalAlt.source.decl)
            continue;
          std::optional<unsigned> callerParamIdx =
              paramIndexOfInFunction(edge.caller, originalAlt.source.decl);
          if (!callerParamIdx)
            continue;

          for (OriginAlternative alt :
               expandGuardedJoinAlternative(originalAlt)) {
            TransferDraft draft;
            draft.edge = &edge;
            draft.calleeParamIndex = calleeParamIdx;
            draft.callerParamIndex = *callerParamIdx;
            draft.alt = std::move(alt);
            draft.callerQN = callerQN;
            draft.calleeQN = calleeQN;
            draft.callerSig = callerSig;
            draft.calleeSig = calleeSig;
            draft.callerNode = callerNode;
            draft.calleeNode = calleeNode;
            draft.span = callSpan;
            draft.pathRendered = pathKey(draft.alt);
            draft.guardText =
                draft.alt.guard ? draft.alt.guard->text : std::string();
            drafts.push_back(std::move(draft));
          }
        }
      }
    }

    // First family shape: one call site has multiple reaching origin
    // alternatives.  This is the p127-style guarded-origin case.  The call
    // span belongs in the family identity because separate calls in the same
    // function are not implicitly siblings.
    std::map<std::string, std::vector<size_t>> sameCallGroups;
    for (size_t i = 0; i < drafts.size(); ++i) {
      const TransferDraft &d = drafts[i];
      sameCallGroups[d.callerNode + "|$" +
                     std::to_string(d.callerParamIndex) + "|" +
                     d.calleeNode + "|$" +
                     std::to_string(d.calleeParamIndex) + "|@" +
                     spanKey(d.span)].push_back(i);
    }
    for (const auto &group : sameCallGroups) {
      std::set<std::string> variants;
      for (size_t i : group.second)
        variants.insert(drafts[i].pathRendered + "|guard=" +
                        drafts[i].guardText);
      if (group.second.size() < 2 || variants.size() < 2)
        continue;
      const TransferDraft &first = drafts[group.second.front()];
      const std::string familyId =
          "branch-family:guarded-origin-alternatives:" + first.callerNode +
          ".$" + std::to_string(first.callerParamIndex) + "->" +
          first.calleeNode + ".$" + std::to_string(first.calleeParamIndex) +
          "@" + spanKey(first.span);
      const std::string origin =
          "multiple reaching origin alternatives at one direct-call site";
      for (size_t i : group.second) {
        TransferDraft &d = drafts[i];
        d.familyId = familyId;
        d.familyKind = "guarded-origin-alternatives";
        d.familyOrigin = origin;
        // Non-local guarded-origin alternatives are not generalized in this
        // metadata patch.  Their closure key remains their exact source
        // family identity.
        d.recursiveClosureKey = familyId;
        d.armKind = "origin-alternative";
        d.armId = familyId + ":arm@" + spanKey(d.span) +
                  ":path=" + d.pathRendered + ":guard=" + d.guardText;
      }
    }

    // Second family shape: multiple direct call sites forward distinct actual
    // paths from the same caller formal to the same callee formal.  This is
    // the p126/p130-style parallel-call-actuals candidate.  It is metadata
    // only; C6g5w1 intentionally makes no claim that every such family must
    // later be collapsed by the solver.
    std::map<std::string, std::vector<size_t>> parallelCallGroups;
    for (size_t i = 0; i < drafts.size(); ++i) {
      const TransferDraft &d = drafts[i];
      if (!d.familyId.empty())
        continue;
      parallelCallGroups[d.callerNode + "|$" +
                         std::to_string(d.callerParamIndex) + "|" +
                         d.calleeNode + "|$" +
                         std::to_string(d.calleeParamIndex)].push_back(i);
    }
    for (const auto &group : parallelCallGroups) {
      std::set<std::string> callSites;
      std::set<std::string> paths;
      for (size_t i : group.second) {
        callSites.insert(spanKey(drafts[i].span));
        paths.insert(drafts[i].pathRendered);
      }
      if (callSites.size() < 2 || paths.size() < 2)
        continue;
      const TransferDraft &first = drafts[group.second.front()];
      const std::string familyId =
          "branch-family:parallel-call-actuals:" + first.callerNode + ".$" +
          std::to_string(first.callerParamIndex) + "->" + first.calleeNode +
          ".$" + std::to_string(first.calleeParamIndex);
      const std::string origin =
          "distinct direct-call actual paths from one caller formal to one callee formal";
      for (size_t i : group.second) {
        TransferDraft &d = drafts[i];
        d.familyId = familyId;
        d.familyKind = "parallel-call-actuals";
        d.familyOrigin = origin;
        // p126/p130 must close only when the exact original parallel family
        // returns on the recursive path, not merely when another call has a
        // similar pair of casts.
        d.recursiveClosureKey = familyId;
        d.armKind = "call-actual-path";
        d.armId = familyId + ":arm@" + spanKey(d.span) +
                  ":path=" + d.pathRendered;
      }
    }

    // C6g5w1b: attach source-local guarded ptrarith arms to one existing
    // ordinary transfer draft.  Do not clone the transfer edge: cloning would
    // change the project solver's input cardinality and violate this patch's
    // metadata-only contract.
    for (const NamedCallEdge &edge : namedCallEdges) {
      if (!edge.caller || !edge.callee)
        continue;
      std::string callerQN = functionQualifiedNameForDependency(edge.caller);
      std::string calleeQN = functionQualifiedNameForDependency(edge.callee);
      std::string callerSig = functionSignatureKey(edge.caller);
      std::string calleeSig = functionSignatureKey(edge.callee);
      std::string callerNode = callerQN;
      if (!callerSig.empty())
        callerNode += "::" + callerSig;
      std::string calleeNode = calleeQN;
      if (!calleeSig.empty())
        calleeNode += "::" + calleeSig;
      const SourceSpan callSpan = sourceSpan(edge.loc);

      for (unsigned calleeParamIdx = 0;
           calleeParamIdx < edge.actuals.size(); ++calleeParamIdx) {
        const NamedCallActual &actual = edge.actuals[calleeParamIdx];
        const auto candidates = guardedLocalPtrArithArmsForActual(
            edge, actual, calleeParamIdx, callerNode, calleeNode, callSpan);
        if (candidates.size() < 2)
          continue;

        const ParmVarDecl *rootParam = candidates.front().rootParam;
        if (!rootParam)
          continue;
        const std::optional<unsigned> rootParamIdx =
            paramIndexOfInFunction(edge.caller, rootParam);
        if (!rootParamIdx)
          continue;
        bool sameRoot = true;
        std::set<std::string> guards;
        for (const auto &candidate : candidates) {
          sameRoot = sameRoot && candidate.rootParam == rootParam;
          guards.insert(candidate.arm.guardText);
        }
        if (!sameRoot || guards.size() < 2)
          continue;

        const std::string familyId =
            "branch-family:guarded-local-ptrarith:" + callerNode + ".$" +
            std::to_string(*rootParamIdx) + "->" + calleeNode + ".$" +
            std::to_string(calleeParamIdx) + "@" + spanKey(callSpan);
        const std::string origin =
            "guarded local pointer-arithmetic alternatives for one call actual";

        // Select a pre-existing ordinary edge for this exact parameter
        // transfer. Its normal actualPath and guard remain untouched.
        TransferDraft *carrier = nullptr;
        for (TransferDraft &draft : drafts) {
          if (draft.edge != &edge ||
              draft.calleeParamIndex != calleeParamIdx ||
              draft.callerParamIndex != *rootParamIdx)
            continue;
          if (!draft.familyId.empty())
            continue;
          carrier = &draft;
          break;
        }
        if (!carrier)
          continue;

        carrier->familyId = familyId;
        carrier->familyKind = "guarded-local-ptrarith";
        carrier->familyOrigin = origin;
        for (const auto &candidate : candidates)
          carrier->branchArms.push_back(candidate.arm);
        // Unlike familyId, this key intentionally matches f.$0 and g.$0 in
        // p127 when their guarded byte-pointer transformers are semantically
        // identical.  It is emitted only as metadata in C6g5w1c.
        carrier->recursiveClosureKey =
            guardedLocalPtrArithRecursiveClosureKey(*rootParamIdx, rootParam,
                                                     carrier->branchArms);
      }
    }

    // Any tagged family that did not opt into the narrow guarded-local
    // semantic key uses exact family identity.  This is intentionally a
    // default, not a generic similarity rule.
    for (TransferDraft &d : drafts) {
      if (!d.familyId.empty() && d.recursiveClosureKey.empty())
        d.recursiveClosureKey = d.familyId;
    }

    std::map<std::string, unsigned> familyMemberCounts;
    for (const TransferDraft &d : drafts) {
      if (d.familyId.empty())
        continue;
      familyMemberCounts[d.familyId] +=
          d.branchArms.empty()
              ? 1u
              : static_cast<unsigned>(d.branchArms.size());
    }

    json::Array arr;
    for (const TransferDraft &draft : drafts) {
      const NamedCallEdge &edge = *draft.edge;
      const OriginAlternative &alt = draft.alt;
      const NamedCallActual &actual = edge.actuals[draft.calleeParamIndex];

      // C6g4c: export direct-call callback bindings alongside ordinary
      // caller-parameter -> callee-parameter transfer edges.  The index
      // builder needs this call-site context to replace a callee core such as
      // $0.$1 with the target callback's parameter summary.
      std::map<unsigned,
               std::vector<const NamedCallEdge::ResolvedHigherOrderActual *>>
          higherOrderByFormal;
      for (const auto &binding : edge.resolvedHigherOrderActuals)
        higherOrderByFormal[binding.calleeFunctionParamIndex].push_back(
            &binding);

      auto makeHigherOrderBindingsJson = [&]() {
        json::Array bindingsJson;
        for (const auto &entry : higherOrderByFormal) {
          const unsigned formalIndex = entry.first;
          const auto &bindings = entry.second;
          json::Object bindingObj{
              {"calleeFunctionParamIndex", static_cast<int64_t>(formalIndex)},
              {"status", bindings.size() == 1 ? "unique" : "multi"}};

          json::Array targets;
          for (const auto *binding : bindings) {
            if (!binding || !binding->target)
              continue;
            const FunctionDecl *target = binding->target;
            const std::string targetQN =
                functionQualifiedNameForDependency(target);
            const std::string targetSig = functionSignatureKey(target);
            json::Object targetObj{
                {"target", functionNameForDependency(target)},
                {"targetQualifiedName", targetQN},
                {"targetSignatureKey", targetSig},
                {"targetPublicLookupKey",
                 SummaryIndex::makePublicLookupKey(targetQN, targetSig)}};
            if (binding->guard)
              targetObj["guard"] = guardJson(*binding->guard);
            else
              targetObj["guard"] = json::Value(nullptr);
            targets.push_back(std::move(targetObj));
          }
          bindingObj["targets"] = std::move(targets);
          bindingsJson.push_back(std::move(bindingObj));
        }
        return bindingsJson;
      };

      json::Object obj{
          {"kind", "direct-call-param-transfer"},
          {"caller", functionNameForDependency(edge.caller)},
          {"callerQualifiedName", draft.callerQN},
          {"callerSignatureKey", draft.callerSig},
          {"callerNode", draft.callerNode},
          {"callee", functionNameForDependency(edge.callee)},
          {"calleeQualifiedName", draft.calleeQN},
          {"calleeSignatureKey", draft.calleeSig},
          {"calleePublicLookupKey",
           SummaryIndex::makePublicLookupKey(draft.calleeQN, draft.calleeSig)},
          {"calleeNode", draft.calleeNode},
          {"callerParamIndex", static_cast<int64_t>(draft.callerParamIndex)},
          {"calleeParamIndex", static_cast<int64_t>(draft.calleeParamIndex)},
          {"actualPathFromCallerParam",
           linkFormat
               ? historyLinkSummaryJson(normalizeObs(alt.pathFromSource))
               : historySummaryJson(normalizeObs(alt.pathFromSource))},
          {"formalType", actual.formalType},
          {"resolvedHigherOrderActuals", makeHigherOrderBindingsJson()},
          {"isFieldFunctionPointerCall", edge.isFieldFunctionPointerCall},
          {"calleeExpr", edge.calleeExprText},
          {"fieldEntity", edge.fieldEntityText},
          {"fieldPath", edge.fieldPathText},
          {"fieldSignatureKey", edge.fieldSignatureKey},
          {"location", sourceSpanJson(draft.span)}};

      if (!draft.familyId.empty()) {
        obj["branchFamily"] = json::Object{
            {"id", draft.familyId},
            {"kind", draft.familyKind},
            {"ownerNode", draft.callerNode},
            {"ownerParamIndex", static_cast<int64_t>(draft.callerParamIndex)},
            {"origin", draft.familyOrigin},
            {"recursiveClosureKey", draft.recursiveClosureKey},
            {"memberCount", static_cast<int64_t>(familyMemberCounts[draft.familyId])},
            {"diagnosticOnly", true}};
        if (draft.branchArms.empty()) {
          obj["branchArm"] = json::Object{
              {"id", draft.armId},
              {"kind", draft.armKind},
              {"familyId", draft.familyId},
              {"actualPath", draft.pathRendered},
              {"originSourceEntity", renderEntity(alt.source)},
              {"callSite", sourceSpanJson(draft.span)},
              {"diagnosticOnly", true}};
        } else {
          json::Array arms;
          for (const BranchFamilyArmDraft &arm : draft.branchArms) {
            arms.push_back(json::Object{
                {"id", arm.id},
                {"kind", arm.kind},
                {"familyId", draft.familyId},
                {"actualPath", arm.actualPath},
                {"guardText", arm.guardText},
                {"originSourceEntity", arm.originSourceEntity},
                {"callSite", sourceSpanJson(arm.originSpan)},
                {"diagnosticOnly", true}});
          }
          obj["branchArms"] = std::move(arms);
        }
      }

      if (alt.guard)
        obj["guard"] = guardJson(*alt.guard);
      else
        obj["guard"] = json::Value(nullptr);

      arr.push_back(std::move(obj));
    }

    return arr;
  }

  json::Array emitSummaryDependencyEdgesJson() const {
    json::Array arr;

    std::vector<const SummaryDependencyEdge *> records;
    records.reserve(summaryDependencyEdges.size());
    for (const auto &edge : summaryDependencyEdges)
      records.push_back(&edge);

    std::sort(records.begin(), records.end(),
              [this](const SummaryDependencyEdge *a,
                     const SummaryDependencyEdge *b) {
                if (sourceSpanLess(a->span, b->span))
                  return true;
                if (sourceSpanLess(b->span, a->span))
                  return false;
                if (a->callerQualifiedName != b->callerQualifiedName)
                  return a->callerQualifiedName < b->callerQualifiedName;
                if (a->calleeQualifiedName != b->calleeQualifiedName)
                  return a->calleeQualifiedName < b->calleeQualifiedName;
                return std::string(summaryDependencyKindName(a->kind)) <
                       std::string(summaryDependencyKindName(b->kind));
              });

    for (const SummaryDependencyEdge *edge : records) {
      json::Object obj{
          {"kind", summaryDependencyKindName(edge->kind)},
          {"caller", edge->caller},
          {"callerQualifiedName", edge->callerQualifiedName},
          {"callerSignatureKey", edge->callerSignatureKey},
          {"callee", edge->callee},
          {"calleeQualifiedName", edge->calleeQualifiedName},
          {"calleeSignatureKey", edge->calleeSignatureKey},
          {"calleePublicLookupKey", edge->calleePublicLookupKey},
          {"calleeExpr", edge->calleeExpr},
          {"via", edge->via},
          {"calleeHasLocalDefinition", edge->calleeHasLocalDefinition},
          {"crossTUCandidate", edge->crossTUCandidate},
          {"importedSummaryCandidate", edge->importedSummaryCandidate},
          {"resolvedBySummaryIndex", edge->resolvedBySummaryIndex},
          {"detail", edge->detail},
          {"location", sourceSpanJson(edge->span)}};

      if (edge->callerArgumentIndex)
        obj["callerArgumentIndex"] = static_cast<int64_t>(*edge->callerArgumentIndex);
      else
        obj["callerArgumentIndex"] = json::Value(nullptr);

      if (edge->calleeParamIndex)
        obj["calleeParamIndex"] = static_cast<int64_t>(*edge->calleeParamIndex);
      else
        obj["calleeParamIndex"] = json::Value(nullptr);

      if (edge->calleeArgumentIndex)
        obj["calleeArgumentIndex"] = static_cast<int64_t>(*edge->calleeArgumentIndex);
      else
        obj["calleeArgumentIndex"] = json::Value(nullptr);

      if (edge->guard)
        obj["guard"] = guardJson(*edge->guard);
      else
        obj["guard"] = json::Value(nullptr);

      arr.push_back(std::move(obj));
    }
    return arr;
  }

  json::Array emitCrossTUSCCMembershipsJson() const {
    json::Array arr;
    for (const auto &rec : collectCrossTUSCCMemberships()) {
      json::Array members;
      for (const auto &m : rec.members)
        members.push_back(m);
      arr.push_back(json::Object{
          {"function", rec.function},
          {"qualifiedName", rec.qualifiedName},
          {"signatureKey", rec.signatureKey},
          {"publicLookupKey", rec.publicLookupKey},
          {"sccId", rec.sccId},
          {"recursive", rec.recursive},
          {"selfLoop", rec.selfLoop},
          {"size", rec.size},
          {"members", std::move(members)}});
    }
    return arr;
  }

